        chapter: 30,
        verse: 11,
        author: 'Tried By Fire',
        authorHandle: '@TriedByFire',
        profileImageUrl: undefined,
        text: `"Gad" means “troop." Maybe this child had a little more of a difficult time when being birthed. Maybe Leah thought of this child as a strong example that Leah was still the more favored one because she was able to have MORE children than Rachel. I am curious about the maids (now concubines) and their thoughts on this matter, though. They were being treated like baby-making houses. More like animals.`,
        likes: 0,
        isLikedByUser: false,
