        author: 'Tried By Fire',
        authorHandle: '@TriedByFire',
        profileImageUrl: undefined,
        text: `God was not done with Rachel. Rachel may not have had any children, but God wanted her to have one. This is an important note to make, because if Rachel never had a child, we would hold very different accounts of history in our hands today. This child will become a very important figure in uniting these very torn people. Jacob has a lot to deal with now, and he may feel a bit over-encumbered with the pressure of keeping his family together. They were fighting over every little thing.`,
