        author: 'Tried By Fire',
        authorHandle: '@TriedByFire',
        profileImageUrl: undefined,
        text: `We must remember that this is all happening under the view of Laban, who has still not given freedom to Jacob after he had worked so long. All of these children are now ventured to journey with Jacob and his four wives back into his homeland. Jacob has a lot to deal with at this moment, and he just wants to go home now. Perhaps he felt that if he was not working for his father-in-law any longer, that it might relieve some of the burden or pressure on his shoulders. He has worked long and hard enough for him.`,
